-- Ripunta gli esami hand-seeded ai corsi di laurea reali equivalenti.
update public.courses set degree_course_id = '00102-l-8-ingegneria-informatica' where degree_course_id = 'dc-inf-polito';
update public.courses set degree_course_id = '00102-l-9-ingegneria-meccanica' where degree_course_id = 'dc-mecc-polito';
update public.courses set degree_course_id = '00101-l-35-matematica' where degree_course_id = 'dc-mat-unito';
update public.courses set degree_course_id = '00101-l-30-fisica' where degree_course_id = 'dc-fis-unito';
update public.courses set degree_course_id = '00101-l-33-economia' where degree_course_id = 'dc-eco-unito';
update public.courses set degree_course_id = '05001-l-31-informatica' where degree_course_id = 'dc-inf-unipi';

-- Rimuove i corsi/atenei placeholder ormai sostituiti dai dati reali.
delete from public.degree_courses where id in ('dc-inf-polito','dc-mecc-polito','dc-mat-unito','dc-fis-unito','dc-eco-unito','dc-inf-unipi');
delete from public.universities where id in ('unito','polito','unipi','unimi');
